import React from 'react';
import './Dashboard.css';  // Import your dashboard-specific CSS
import companyLogo from './images/cadmax.png'; // Path to the logo image

const Dashboard = () => {
  return (
    <div className="dashboard-container">
      {/* Company Logo in the top-left corner */}
      <img src={companyLogo} alt="Company Logo" className="company-logo" />

      {/* Buttons under the company logo */}
      <div className="button-container">
        <button className="dashboard-btn">Button 1</button>
        <button className="dashboard-btn">Button 2</button>
        <button className="dashboard-btn">Button 3</button>
      </div>

      <div className="dashboard-content">
        <h1>Welcome to the Dashboard</h1>
        <p>Here is the content of the dashboard...</p>
        {/* Other dashboard content */}
      </div>
    </div>
  );
};

export default Dashboard;
